from fastmcp import Server
import inspect

def create_proxy_server(backend_server: Server) -> Server:
    """
    Create a transparent proxy FastMCP server that forwards all tool 
    and resource requests to a backend FastMCP server instance.

    Args:
        backend_server: The backend FastMCP Server instance to proxy requests through.

    Returns:
        A new FastMCP Server instance that acts as a transparent proxy.
    """
    proxy = Server("proxy")

    def make_forwarding_handler(backend_handler):
        """Create a handler that forwards calls to the backend handler."""
        if inspect.iscoroutinefunction(backend_handler):
            async def forward(*args, **kwargs):
                return await backend_handler(*args, **kwargs)
            return forward
        else:
            def forward(*args, **kwargs):
                return backend_handler(*args, **kwargs)
            return forward

    # Proxy all tools from backend
    proxy._tools = {}
    if hasattr(backend_server, '_tools') and backend_server._tools:
        for tool_name, tool_entry in backend_server._tools.items():
            backend_handler = tool_entry.get('handler') if isinstance(tool_entry, dict) else tool_entry
            forward_handler = make_forwarding_handler(backend_handler)

            if isinstance(tool_entry, dict):
                proxy._tools[tool_name] = {
                    'handler': forward_handler,
                    **{k: v for k, v in tool_entry.items() if k != 'handler'}
                }
            else:
                proxy._tools[tool_name] = forward_handler

    # Proxy all resources from backend
    proxy._resources = {}
    if hasattr(backend_server, '_resources') and backend_server._resources:
        for resource_name, resource_entry in backend_server._resources.items():
            backend_handler = resource_entry.get('handler') if isinstance(resource_entry, dict) else resource_entry
            forward_handler = make_forwarding_handler(backend_handler)

            if isinstance(resource_entry, dict):
                proxy._resources[resource_name] = {
                    'handler': forward_handler,
                    **{k: v for k, v in resource_entry.items() if k != 'handler'}
                }
            else:
                proxy._resources[resource_name] = forward_handler

    return proxy


if __name__ == "__main__":
    # Example: create backend and proxy
    backend = Server("backend")

    @backend.tool()
    def echo(message: str) -> str:
        """Echo the input message."""
        return f"Echo: {message}"

    @backend.resource()
    def status() -> str:
        """Get server status."""
        return "Backend running"

    # Create transparent proxy
    proxy = create_proxy_server(backend)

    print(f"✓ Proxy created with {len(proxy._tools)} tools and {len(proxy._resources)} resources")

